import React, { useState } from 'react';
import { MapPin, Camera, Send } from 'lucide-react';

function Report() {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    category: '',
    location: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Report submitted:', formData);
    // TODO: API call to submit issue
    alert('Issue reported successfully!');
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
      <h1 style={{ 
        fontSize: '28px', 
        fontWeight: '700', 
        color: '#000080',
        marginBottom: '10px'
      }}>
        Report an Issue
      </h1>
      <p style={{ color: '#666', marginBottom: '30px' }}>
        Help improve your community by reporting civic issues
      </p>

      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: '20px' }}>
          <label style={{ 
            display: 'block', 
            fontWeight: '600', 
            marginBottom: '8px',
            color: '#000080'
          }}>
            Issue Title *
          </label>
          <input
            type="text"
            name="title"
            value={formData.title}
            onChange={handleChange}
            required
            placeholder="Brief description of the issue"
            style={{
              width: '100%',
              padding: '12px',
              border: '2px solid #E0E0E0',
              borderRadius: '8px',
              fontSize: '16px',
              fontFamily: 'Poppins, sans-serif'
            }}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ 
            display: 'block', 
            fontWeight: '600', 
            marginBottom: '8px',
            color: '#000080'
          }}>
            Category *
          </label>
          <select
            name="category"
            value={formData.category}
            onChange={handleChange}
            required
            style={{
              width: '100%',
              padding: '12px',
              border: '2px solid #E0E0E0',
              borderRadius: '8px',
              fontSize: '16px',
              fontFamily: 'Poppins, sans-serif'
            }}
          >
            <option value="">Select a category</option>
            <option value="roads">Roads & Infrastructure</option>
            <option value="water">Water Supply</option>
            <option value="electricity">Electricity</option>
            <option value="sanitation">Sanitation</option>
            <option value="safety">Public Safety</option>
            <option value="other">Other</option>
          </select>
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ 
            display: 'block', 
            fontWeight: '600', 
            marginBottom: '8px',
            color: '#000080'
          }}>
            Description *
          </label>
          <textarea
            name="description"
            value={formData.description}
            onChange={handleChange}
            required
            placeholder="Provide detailed information about the issue"
            rows="5"
            style={{
              width: '100%',
              padding: '12px',
              border: '2px solid #E0E0E0',
              borderRadius: '8px',
              fontSize: '16px',
              fontFamily: 'Poppins, sans-serif',
              resize: 'vertical'
            }}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ 
            display: 'block', 
            fontWeight: '600', 
            marginBottom: '8px',
            color: '#000080'
          }}>
            <MapPin size={18} style={{ display: 'inline', marginRight: '5px' }} />
            Location *
          </label>
          <input
            type="text"
            name="location"
            value={formData.location}
            onChange={handleChange}
            required
            placeholder="Enter location or address"
            style={{
              width: '100%',
              padding: '12px',
              border: '2px solid #E0E0E0',
              borderRadius: '8px',
              fontSize: '16px',
              fontFamily: 'Poppins, sans-serif'
            }}
          />
        </div>

        <div style={{ marginBottom: '30px' }}>
          <label style={{ 
            display: 'block', 
            fontWeight: '600', 
            marginBottom: '8px',
            color: '#000080'
          }}>
            <Camera size={18} style={{ display: 'inline', marginRight: '5px' }} />
            Add Photo (Optional)
          </label>
          <input
            type="file"
            accept="image/*"
            style={{
              width: '100%',
              padding: '12px',
              border: '2px solid #E0E0E0',
              borderRadius: '8px',
              fontSize: '16px',
              fontFamily: 'Poppins, sans-serif'
            }}
          />
        </div>

        <button
          type="submit"
          style={{
            width: '100%',
            padding: '16px',
            backgroundColor: '#FF9933',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            fontSize: '18px',
            fontWeight: '600',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '10px',
            fontFamily: 'Poppins, sans-serif'
          }}
        >
          <Send size={20} />
          Submit Report
        </button>
      </form>
    </div>
  );
}

export default Report;
